 /* --- VCPdesktop Push Placeholder --- */
 .vcp-desktop-push-placeholder {
@@ -3336,3 +2949,163 @@ body[data-vcp-theme="light"] .vcp-flowlock-bubble.state-heartbeat .vcp-flowlock-
 body[data-vcp-theme="light"] .vcp-flowlock-bubble.state-prompt .vcp-flowlock-icon {
