 }
+
+
+/* Host-owned checkpoint: raw historical data, never an executable rich-content island. */
+.vcp-context-checkpoint {
+    min-width: 220px;
+    max-width: 100%;
+    border: 1px solid var(--border-color);
+    border-left: 3px solid var(--highlight-text);
+    border-radius: 8px;
+    background: var(--secondary-bg);
+    color: var(--primary-text);
+    font-size: 13px;
+    text-align: left;
+}
+.vcp-context-checkpoint > summary {
+    padding: 10px 14px;
+    cursor: pointer;
+    font-weight: 600;
+    user-select: none;
+}
+.vcp-context-checkpoint > summary:focus-visible {
+    outline: 2px solid var(--highlight-text);
+    outline-offset: 2px;
+}
+.vcp-context-checkpoint-body {
+    padding: 12px 14px;
+    border-top: 1px solid var(--border-color);
+    max-height: 480px;
+    overflow: auto;
+    white-space: pre-wrap;
+    overflow-wrap: anywhere;
+    font-family: var(--vcp-chat-code-font-family, monospace);
+    font-size: 12px;
+    line-height: 1.65;
+}
+.vcp-compaction-spinner {
+    display: inline-block;
+    width: 16px;
+    height: 16px;
+    border: 2px solid currentColor;
+    border-right-color: transparent;
+    border-radius: 50%;
+    animation: vcp-icon-rotate 0.9s linear infinite;
+}
+@media (prefers-reduced-motion: reduce) {
+    .vcp-compaction-spinner { animation: none; }
+}
+
+
+/* Host-owned audit digest inside a checkpoint card: shown only when a signal fired. */
+.vcp-context-checkpoint-audit {
+    margin: 0 0 12px 0;
+    padding: 8px 12px;
+    border: 1px dashed var(--border-color);
+    border-left: 3px solid var(--highlight-text);
+    border-radius: 6px;
+    background: var(--primary-bg);
+    white-space: pre-wrap;
+    overflow-wrap: anywhere;
+}
+.vcp-context-checkpoint-audit-line + .vcp-context-checkpoint-audit-line {
+    margin-top: 4px;
+}
+
+
+/* Chart references: stable geometry, one isolated live frame per chart id. */
+.vcp-chart-embed {
+    box-sizing: border-box;
+    display: flex;
+    flex-direction: column;
+    width: 100%;
+    min-width: 0;
+    margin: 12px 0;
+    overflow: hidden;
+    border: 1px solid color-mix(in srgb, currentColor 18%, transparent);
+    border-radius: 10px;
+    color: inherit;
+    background: color-mix(in srgb, currentColor 4%, transparent);
+    contain: layout paint;
+}
+
+.vcp-chart-header {
+    box-sizing: border-box;
+    display: flex;
+    flex: 0 0 42px;
+    align-items: center;
+    justify-content: space-between;
+    gap: 8px;
+    padding: 6px 10px;
+    border-bottom: 1px solid color-mix(in srgb, currentColor 12%, transparent);
+    font: 12px/1.4 system-ui, sans-serif;
+}
+
+.vcp-chart-header strong {
+    min-width: 0;
+    overflow: hidden;
+    text-overflow: ellipsis;
+    white-space: nowrap;
+}
+
+.vcp-chart-header > div {
+    display: flex;
+    flex-shrink: 0;
+    gap: 5px;
+}
+
+.vcp-chart-header button {
+    padding: 3px 7px;
+    border: 1px solid color-mix(in srgb, currentColor 20%, transparent);
+    border-radius: 5px;
+    color: inherit;
+    background: transparent;
+    font: inherit;
+    cursor: pointer;
+}
+
+.vcp-chart-header button:hover,
+.vcp-chart-header button:focus-visible {
+    background: color-mix(in srgb, currentColor 12%, transparent);
+}
+
+.vcp-chart-stage {
+    position: relative;
+    flex: 1;
+    min-height: 0;
+    overflow: hidden;
+}
+
+.vcp-chart-poster {
+    position: absolute;
+    inset: 0;
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    gap: 12px;
+    padding: 16px;
+    text-align: center;
+}
+
+.vcp-chart-status {
+    max-width: 100%;
+    overflow-wrap: anywhere;
+    opacity: .75;
+    font: 12px/1.5 system-ui, sans-serif;
+}
+
+.vcp-chart-embed-frame {
+    position: absolute;
+    inset: 0;
+    display: block;
+    width: 100%;
+    height: 100%;
+    border: 0;
+    background: transparent;
+}
+
+.vcp-chart-embed.is-playing .vcp-chart-poster {
+    visibility: hidden;
+}
